import 'dart:math';

import 'package:battle_backend/src/appwrite_rows.dart';
import 'package:battle_backend/src/refused.dart';
import 'package:battle_backend/src/rows.dart';
import 'package:battle_protocol/battle_protocol.dart';
import 'package:hawkbee_schema/hawkbee_schema.dart';

/// {@template api_keys}
/// The API keys of the accounts (AI-04, decisions 158, 161; stack decision
/// 6): one per account, generated by the server, shown once and stored
/// only as its hash. A new key replaces the account's previous one. The
/// user revokes their own key and an admin any key; a revoked key is
/// refused from the next call on.
/// {@endtemplate}
final class ApiKeys {
  /// {@macro api_keys}
  new({required this.rows, required this.admins, Random? random})
    : _random = random ?? Random.secure();

  /// The tables.
  final Rows rows;

  /// Who is an admin.
  final Admins admins;

  final Random _random;

  /// A new key for [caller], replacing their previous one: its value, the
  /// one time it is shown.
  Future<String> create({required String caller}) async {
    final key = ApiKey.generate(_random);
    await rows.put(
      AppwriteIds.apiKeysTableId,
      caller,
      ApiKeyRow(accountId: caller, hash: key.hash).toData(),
    );
    return key.value;
  }

  /// [caller] revokes the key of [accountId]: their own, or any key for
  /// an admin.
  Future<void> revoke({
    required String caller,
    required String accountId,
  }) async {
    if (caller != accountId && !await admins.isAdmin(caller)) {
      throw Refused.notAdmin;
    }
    final data =
        await rows.get(AppwriteIds.apiKeysTableId, accountId) ??
        (throw Refused.unknown('key'));
    await rows.put(
      AppwriteIds.apiKeysTableId,
      accountId,
      ApiKeyRow(
        accountId: accountId,
        hash: ApiKeyRow.fromData(data).hash,
        revoked: true,
      ).toData(),
    );
  }

  /// The account [key] signs in as (decision 162); null for a key that is
  /// not one, unknown, or revoked.
  Future<String?> accountOf(String key) async {
    final ApiKey parsed;
    try {
      parsed = ApiKey.parse(key);
    } on FormatException {
      return null;
    }
    for (final row in await rows.find(AppwriteIds.apiKeysTableId, {
      'hash': parsed.hash,
    })) {
      final stored = ApiKeyRow.fromData(row.data);
      if (!stored.revoked) return stored.accountId;
    }
    return null;
  }
}
